import sys
import re

def main():
    text = sys.stdin.read()
    env = {}
    assign_re = re.compile(r'^\s*([A-Za-z_]\w*)\s*<-\s*(.+?)\s*;?\s*$')
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith('//'):
            continue
        # strip trailing inline comments
        if '//' in line:
            line = line.split('//', 1)[0].strip()
            if not line:
                continue
        m = assign_re.match(line)
        if not m:
            continue
        target, expr = m.group(1), m.group(2).strip().rstrip(';').strip()
        if re.fullmatch(r'-?\d+', expr):
            env[target] = int(expr)
        elif re.fullmatch(r'[A-Za-z_]\w*', expr):
            env[target] = env.get(expr, 0)
        else:
            # Fallback: evaluate simple arithmetic expressions using current variables
            try:
                env[target] = eval(expr, {"__builtins__": {}}, dict(env))
            except Exception:
                continue
    out = []
    for name in ['a', 'b', 'c', 'd', 'TMP']:
        out.append(f"{name} ?= {env.get(name, 0)};")
    print(' '.join(out))

if __name__ == '__main__':
    main()
